### 4.6 Specification 5: `poc/app/js/app.js`
```javascript
/**
 * CineJoy On-Device PoC Test Harness
 * Target: LG 32LR686BPSA (webOS 8.5.0, Chromium 94)
 * File: poc/app/js/app.js
 *
 * Responsibilities:
 * 1. Initialize Luna Keepalive Subscription (luna://com.cinejoy.poc.service/keepalive).
 * 2. Poll On-Device Service Health (http://127.0.0.1:8088/health).
 * 3. Request TMDB 550 (Fight Club) Stream via http://127.0.0.1:8088/api/stream.
 * 4. Load Stream into HTML5 <video> and track events & buffer health.
 * 5. Provide 10-Foot Spatial D-Pad Navigation & Remote Key Mappings.
 */

(function (window, document) {
  'use strict';

  // =========================================================================
  // 1. Configuration & Global State
  // =========================================================================
  var CONFIG = {
    DEFAULT_PORT: 8088,
    HEALTH_POLL_INTERVAL_MS: 3000,
    TMDB_ID: 550,
    MEDIA_TYPE: 'movie',
    SERVER: 'secret',
    SAFE_RSS_THRESHOLD_MB: 50.0
  };

  var state = {
    activePort: CONFIG.DEFAULT_PORT,
    serviceOnline: false,
    lunaSubscribed: false,
    resolvedStreamUrl: null,
    focusedControlIdx: 0,
    healthPollTimer: null,
    logCount: 0
  };

  // DOM Cache
  var dom = {};

  // =========================================================================
  // 2. Logging & UI Helpers
  // =========================================================================
  function getTimestamp() {
    var now = new Date();
    var h = String(now.getHours()).padStart(2, '0');
    var m = String(now.getMinutes()).padStart(2, '0');
    var s = String(now.getSeconds()).padStart(2, '0');
    return '[' + h + ':' + m + ':' + s + ']';
  }

  function addLog(message, type) {
    if (!dom.eventLog) return;
    state.logCount++;
    var entry = document.createElement('div');
    entry.className = 'log-entry ' + (type ? 'log-' + type : 'log-info');
    entry.textContent = getTimestamp() + ' ' + message;
    dom.eventLog.appendChild(entry);
    dom.eventLog.scrollTop = dom.eventLog.scrollHeight;
    if (dom.logCount) {
      dom.logCount.textContent = state.logCount + ' events';
    }
  }

  function formatTime(seconds) {
    if (isNaN(seconds) || seconds < 0 || !isFinite(seconds)) return '00:00:00';
    var totalSec = Math.floor(seconds);
    var h = Math.floor(totalSec / 3600);
    var m = Math.floor((totalSec % 3600) / 60);
    var s = totalSec % 60;
    return String(h).padStart(2, '0') + ':' +
           String(m).padStart(2, '0') + ':' +
           String(s).padStart(2, '0');
  }

  function getBaseUrl() {
    return 'http://127.0.0.1:' + state.activePort;
  }

  // =========================================================================
  // 3. Luna Bus Keepalive Subscription (Triple-Shield Frontend Component)
  // =========================================================================
  function initLunaKeepalive() {
    var serviceUri = 'luna://com.cinejoy.poc.service';
    var method = 'keepalive';

    addLog('Establishing Luna keepalive subscription...', 'info');

    // Method 1: Official webOSTV.js
    if (window.webOS && window.webOS.service && typeof window.webOS.service.request === 'function') {
      try {
        window.webOS.service.request(serviceUri, {
          method: method,
          parameters: { subscribe: true },
          subscribe: true,
          onSuccess: function (res) {
            handleLunaSuccess(res);
          },
          onFailure: function (err) {
            handleLunaFailure(err);
          }
        });
        return;
      } catch (err) {
        addLog('webOSTV.service.request error: ' + err.message, 'warn');
      }
    }

    // Method 2: Direct PalmServiceBridge / WebOSServiceBridge
    var Bridge = window.PalmServiceBridge || window.WebOSServiceBridge;
    if (Bridge) {
      try {
        var bridge = new Bridge();
        bridge.onservicecallback = function (msg) {
          try {
            var res = JSON.parse(msg);
            if (res.returnValue) {
              handleLunaSuccess(res);
            } else {
              handleLunaFailure(res);
            }
          } catch (e) {
            addLog('Bridge parse error: ' + e.message, 'error');
          }
        };
        bridge.call(serviceUri + '/' + method, JSON.stringify({ subscribe: true }));
        window._pocLunaBridge = bridge;
        return;
      } catch (err) {
        addLog('Native bridge instantiation error: ' + err.message, 'error');
      }
    }

    // Method 3: Desktop Browser / Emulation Fallback
    dom.lunaStatus.textContent = 'Simulated / Not on TV';
    dom.lunaStatus.className = 'metric-value warn';
    addLog('Running in standard browser (PalmServiceBridge unavailable)', 'warn');
  }

  function handleLunaSuccess(res) {
    state.lunaSubscribed = true;
    if (res.port && res.port !== state.activePort) {
      state.activePort = res.port;
      dom.healthPort.textContent = String(res.port);
      addLog('Dynamic port reported by service: ' + res.port, 'info');
    }
    dom.lunaStatus.textContent = 'Active (Uptime: ' + Math.round(res.uptime || 0) + 's)';
    dom.lunaStatus.className = 'metric-value highlight';
    addLog('Luna keepalive subscription active: port ' + state.activePort, 'success');
  }

  function handleLunaFailure(err) {
    state.lunaSubscribed = false;
    var errMsg = err.errorText || err.errorCode || JSON.stringify(err);
    dom.lunaStatus.textContent = 'Failed: ' + errMsg;
    dom.lunaStatus.className = 'metric-value error';
    addLog('Luna keepalive failed: ' + errMsg, 'error');
  }

  // =========================================================================
  // 4. On-Device Service Health Polling
  // =========================================================================
  function pollHealth() {
    var url = getBaseUrl() + '/health';
    fetch(url, { cache: 'no-store' })
      .then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.json();
      })
      .then(function (data) {
        state.serviceOnline = true;
        dom.connIndicator.textContent = 'LIVE';
        dom.connIndicator.className = 'status-pill status-live';
        dom.serviceDot.className = 'status-dot dot-green';

        dom.healthStatus.textContent = 'OK (' + (data.mode || 'on-device') + ')';
        dom.healthStatus.className = 'metric-value highlight';
        dom.healthPort.textContent = String(state.activePort);

        var uptimeSec = Math.round(data.uptime || 0);
        dom.healthUptime.textContent = formatTime(uptimeSec) + ' (' + uptimeSec + 's)';

        if (data.memory && data.memory.rss) {
          var rssMB = (data.memory.rss / (1024 * 1024)).toFixed(1);
          dom.healthRss.textContent = rssMB + ' MB';
          if (parseFloat(rssMB) > CONFIG.SAFE_RSS_THRESHOLD_MB) {
            dom.healthRss.className = 'metric-value warn';
          } else {
            dom.healthRss.className = 'metric-value highlight';
          }
        }

        // If stream hasn't been loaded yet, initiate resolution now that service is verified
        if (!state.resolvedStreamUrl) {
          resolveStream();
        }
      })
      .catch(function (err) {
        state.serviceOnline = false;
        dom.connIndicator.textContent = 'SERVICE OFFLINE';
        dom.connIndicator.className = 'status-pill status-error';
        dom.serviceDot.className = 'status-dot dot-red';
        dom.healthStatus.textContent = 'Unreachable';
        dom.healthStatus.className = 'metric-value error';
        addLog('Health ping failed: ' + err.message, 'error');
      });
  }

  // =========================================================================
  // 5. Stream Resolution & CDN Gateway Trigger
  // =========================================================================
  function resolveStream() {
    dom.streamStatus.textContent = 'Resolving TMDB 550 on ' + CONFIG.SERVER + '...';
    dom.streamStatus.className = 'metric-value warn';
    dom.streamDot.className = 'status-dot dot-yellow';
    showSpinner('Resolving Stream...');
    addLog('Requesting stream for TMDB ' + CONFIG.TMDB_ID + ' (Server: ' + CONFIG.SERVER + ')...', 'info');

    var queryUrl = getBaseUrl() + '/api/stream?tmdbId=' + CONFIG.TMDB_ID +
                   '&type=' + CONFIG.MEDIA_TYPE +
                   '&server=' + encodeURIComponent(CONFIG.SERVER);

    fetch(queryUrl, { cache: 'no-store' })
      .then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.json();
      })
      .then(function (data) {
        if (!data.success || !data.streamUrl) {
          throw new Error(data.error || 'No streamUrl returned');
        }
        state.resolvedStreamUrl = data.streamUrl;
        dom.streamStatus.textContent = 'Resolved via ' + (data.server || CONFIG.SERVER);
        dom.streamStatus.className = 'metric-value highlight';
        dom.streamDot.className = 'status-dot dot-green';
        dom.streamUrl.textContent = data.streamUrl;
        addLog('Stream resolved successfully!', 'success');
        addLog('Stream URL: ' + data.streamUrl, 'info');

        attachStreamToPlayer(data.streamUrl);
      })
      .catch(function (err) {
        hideSpinner();
        dom.streamStatus.textContent = 'Resolution Error: ' + err.message;
        dom.streamStatus.className = 'metric-value error';
        dom.streamDot.className = 'status-dot dot-red';
        addLog('Stream resolution failed: ' + err.message, 'error');
      });
  }

  // =========================================================================
  // 6. Video Player Attachment & Telemetry Listeners
  // =========================================================================
  function attachStreamToPlayer(url) {
    var video = dom.video;
    if (!video) return;

    showSpinner('Loading Video...');
    addLog('Attaching stream to <video src="...">', 'player');

    // Reset element
    video.pause();
    video.src = url;
    video.load();

    var playPromise = video.play();
    if (playPromise !== undefined) {
      playPromise.catch(function (err) {
        addLog('Auto-play blocked or waiting: ' + err.message, 'warn');
      });
    }
  }

  function bindVideoListeners() {
    var v = dom.video;
    if (!v) return;

    var events = [
      'loadstart', 'loadedmetadata', 'loadeddata', 'canplay',
      'canplaythrough', 'playing', 'pause', 'waiting', 'seeking',
      'seeked', 'timeupdate', 'progress', 'ended', 'error'
    ];

    events.forEach(function (evtName) {
      v.addEventListener(evtName, function () {
        handleVideoEvent(evtName);
      });
    });
  }

  function handleVideoEvent(evtName) {
    var v = dom.video;
    if (!v) return;

    // Update Player State Display
    dom.playerState.textContent = evtName.toUpperCase();
    dom.playerReadyState.textContent = getReadyStateName(v.readyState);
    dom.playerNetworkState.textContent = getNetworkStateName(v.networkState);

    switch (evtName) {
      case 'loadstart':
        dom.playerDot.className = 'status-dot dot-yellow';
        showSpinner('Connecting Stream...');
        addLog('Video: loadstart', 'player');
        break;

      case 'loadedmetadata':
        dom.timeDuration.textContent = formatTime(v.duration);
        addLog('Video: loadedmetadata (Duration: ' + formatTime(v.duration) + ')', 'player');
        break;

      case 'canplay':
        hideSpinner();
        dom.playerDot.className = 'status-dot dot-green';
        addLog('Video: canplay', 'player');
        break;

      case 'playing':
        hideSpinner();
        dom.playerDot.className = 'status-dot dot-green';
        dom.btnPlayPause.querySelector('.btn-label').textContent = 'Pause';
        dom.btnPlayPause.querySelector('.btn-icon').textContent = '⏸';
        addLog('Video: playing', 'player');
        break;

      case 'pause':
        dom.btnPlayPause.querySelector('.btn-label').textContent = 'Play';
        dom.btnPlayPause.querySelector('.btn-icon').textContent = '▶';
        addLog('Video: pause', 'player');
        break;

      case 'waiting':
        dom.playerDot.className = 'status-dot dot-yellow';
        showSpinner('Buffering...');
        addLog('Video: waiting (buffering)', 'warn');
        break;

      case 'error':
        hideSpinner();
        dom.playerDot.className = 'status-dot dot-red';
        var errCode = v.error ? v.error.code : 'UNKNOWN';
        var errMsg = v.error ? v.error.message : 'Video playback error';
        dom.playerState.textContent = 'ERROR (' + errCode + ')';
        dom.playerState.className = 'metric-value error';
        addLog('Video error [' + errCode + ']: ' + errMsg, 'error');
        break;

      case 'timeupdate':
        updateTimeline();
        break;

      case 'progress':
        updateBufferInfo();
        break;
    }
  }

  function updateTimeline() {
    var v = dom.video;
    if (!v) return;
    dom.timeCurrent.textContent = formatTime(v.currentTime);
    if (v.duration && v.duration > 0) {
      var pct = (v.currentTime / v.duration) * 100;
      dom.playBar.style.width = Math.min(100, Math.max(0, pct)) + '%';
    }
    updateBufferInfo();
  }

  function updateBufferInfo() {
    var v = dom.video;
    if (!v || !v.buffered || v.buffered.length === 0) {
      dom.playerBuffer.textContent = '0.0s';
      dom.bufferBar.style.width = '0%';
      return;
    }

    var cur = v.currentTime || 0;
    var dur = v.duration || 1;
    var maxEnd = 0;

    for (var i = 0; i < v.buffered.length; i++) {
      var bStart = v.buffered.start(i);
      var bEnd = v.buffered.end(i);
      if (cur >= bStart && cur <= bEnd) {
        maxEnd = bEnd;
        break;
      }
      if (bEnd > maxEnd) maxEnd = bEnd;
    }

    var ahead = Math.max(0, maxEnd - cur);
    dom.playerBuffer.textContent = ahead.toFixed(1) + 's';
    var bufPct = (maxEnd / dur) * 100;
    dom.bufferBar.style.width = Math.min(100, Math.max(0, bufPct)) + '%';
  }

  function getReadyStateName(code) {
    var states = ['HAVE_NOTHING (0)', 'HAVE_METADATA (1)', 'HAVE_CURRENT_DATA (2)', 'HAVE_FUTURE_DATA (3)', 'HAVE_ENOUGH_DATA (4)'];
    return states[code] || ('UNKNOWN (' + code + ')');
  }

  function getNetworkStateName(code) {
    var states = ['NETWORK_EMPTY (0)', 'NETWORK_IDLE (1)', 'NETWORK_LOADING (2)', 'NETWORK_NO_SOURCE (3)'];
    return states[code] || ('UNKNOWN (' + code + ')');
  }

  function showSpinner(msg) {
    if (dom.spinnerText) dom.spinnerText.textContent = msg || 'Buffering...';
    if (dom.videoSpinner) dom.videoSpinner.classList.remove('hidden');
  }

  function hideSpinner() {
    if (dom.videoSpinner) dom.videoSpinner.classList.add('hidden');
  }

  // =========================================================================
  // 7. Interactive TV Controls Actions
  // =========================================================================
  function togglePlayPause() {
    var v = dom.video;
    if (!v) return;
    if (v.paused) {
      v.play().catch(function (e) { addLog('Play error: ' + e.message, 'warn'); });
    } else {
      v.pause();
    }
  }

  function seekRelative(offsetSeconds) {
    var v = dom.video;
    if (!v) return;
    var target = (v.currentTime || 0) + offsetSeconds;
    target = Math.max(0, Math.min(v.duration || target, target));
    v.currentTime = target;
    addLog('Seek ' + (offsetSeconds > 0 ? '+' : '') + offsetSeconds + 's -> ' + formatTime(target), 'player');
  }

  function reloadStream() {
    addLog('Reloading stream from scratch...', 'info');
    if (dom.video) {
      dom.video.pause();
      dom.video.removeAttribute('src');
      dom.video.load();
    }
    state.resolvedStreamUrl = null;
    resolveStream();
  }

  function pingHealthManual() {
    addLog('Manual health ping triggered...', 'info');
    pollHealth();
  }

  // =========================================================================
  // 8. 10-Foot Spatial D-Pad Navigation & Remote Key Handlers
  // =========================================================================
  var buttons = [];

  function initNavigation() {
    buttons = Array.prototype.slice.call(document.querySelectorAll('.tv-btn'));
    if (buttons.length === 0) return;

    // Focus initial button
    setFocus(0);

    // Click listeners
    dom.btnPlayPause.addEventListener('click', togglePlayPause);
    dom.btnSeekBack.addEventListener('click', function () { seekRelative(-15); });
    dom.btnSeekFwd.addEventListener('click', function () { seekRelative(15); });
    dom.btnReload.addEventListener('click', reloadStream);
    dom.btnPingHealth.addEventListener('click', pingHealthManual);

    // Focus & hover sync
    buttons.forEach(function (btn, idx) {
      btn.addEventListener('focus', function () { setFocus(idx, false); });
      btn.addEventListener('mouseenter', function () { setFocus(idx, true); });
    });

    // Remote & Keyboard Listener
    window.addEventListener('keydown', handleKeyDown);
  }

  function setFocus(idx, triggerHtmlFocus) {
    if (idx < 0) idx = 0;
    if (idx >= buttons.length) idx = buttons.length - 1;

    buttons.forEach(function (btn) { btn.classList.remove('focused'); });
    state.focusedControlIdx = idx;
    buttons[idx].classList.add('focused');
    if (triggerHtmlFocus !== false) {
      buttons[idx].focus();
    }
  }

  function handleKeyDown(evt) {
    var keyCode = evt.keyCode;

    switch (keyCode) {
      // D-Pad Left
      case 37:
        evt.preventDefault();
        setFocus((state.focusedControlIdx - 1 + buttons.length) % buttons.length);
        break;

      // D-Pad Right
      case 39:
        evt.preventDefault();
        setFocus((state.focusedControlIdx + 1) % buttons.length);
        break;

      // D-Pad Enter / OK
      case 13:
        evt.preventDefault();
        if (buttons[state.focusedControlIdx]) {
          buttons[state.focusedControlIdx].click();
        }
        break;

      // Remote Play
      case 415:
        evt.preventDefault();
        if (dom.video && dom.video.paused) dom.video.play();
        break;

      // Remote Pause
      case 19:
        evt.preventDefault();
        if (dom.video && !dom.video.paused) dom.video.pause();
        break;

      // Remote Play/Pause Toggle
      case 179:
        evt.preventDefault();
        togglePlayPause();
        break;

      // Remote Rewind
      case 412:
      case 227:
        evt.preventDefault();
        seekRelative(-15);
        break;

      // Remote Fast Forward
      case 417:
      case 228:
        evt.preventDefault();
        seekRelative(15);
        break;

      // Remote Back Key (webOS: 461, Esc: 27)
      case 461:
      case 27:
        evt.preventDefault();
        addLog('Back key pressed - exiting application', 'info');
        if (window.webOS && typeof window.webOS.platformBack === 'function') {
          window.webOS.platformBack();
        } else if (window.close) {
          window.close();
        }
        break;
    }
  }

  // =========================================================================
  // 9. Bootstrap & Initialization
  // =========================================================================
  function init() {
    // Cache DOM Elements
    dom.connIndicator = document.getElementById('conn-indicator');
    dom.video = document.getElementById('poc-video');
    dom.videoSpinner = document.getElementById('video-spinner');
    dom.spinnerText = document.getElementById('spinner-text');
    dom.bufferBar = document.getElementById('buffer-bar');
    dom.playBar = document.getElementById('play-bar');
    dom.timeCurrent = document.getElementById('time-current');
    dom.timeDuration = document.getElementById('time-duration');
    dom.serviceDot = document.getElementById('service-dot');
    dom.streamDot = document.getElementById('stream-dot');
    dom.playerDot = document.getElementById('player-dot');
    dom.healthStatus = document.getElementById('health-status');
    dom.healthPort = document.getElementById('health-port');
    dom.healthUptime = document.getElementById('health-uptime');
    dom.healthRss = document.getElementById('health-rss');
    dom.lunaStatus = document.getElementById('luna-status');
    dom.streamServer = document.getElementById('stream-server');
    dom.streamStatus = document.getElementById('stream-status');
    dom.streamUrl = document.getElementById('stream-url');
    dom.playerState = document.getElementById('player-state');
    dom.playerBuffer = document.getElementById('player-buffer');
    dom.playerReadyState = document.getElementById('player-ready-state');
    dom.playerNetworkState = document.getElementById('player-network-state');
    dom.eventLog = document.getElementById('event-log');
    dom.logCount = document.getElementById('log-count');

    dom.btnPlayPause = document.getElementById('btn-play-pause');
    dom.btnSeekBack = document.getElementById('btn-seek-back');
    dom.btnSeekFwd = document.getElementById('btn-seek-fwd');
    dom.btnReload = document.getElementById('btn-reload');
    dom.btnPingHealth = document.getElementById('btn-ping-health');

    addLog('Booting CineJoy On-Device PoC Test Harness...', 'info');

    // Setup Video Listeners
    bindVideoListeners();

    // Setup Remote & D-pad Navigation
    initNavigation();

    // Establish Luna Keepalive Subscription
    initLunaKeepalive();

    // First Health Check & Start Polling Timer
    pollHealth();
    state.healthPollTimer = setInterval(pollHealth, CONFIG.HEALTH_POLL_INTERVAL_MS);
  }

  // Launch on DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})(window, document);
